-- ============================================================
-- csssl 系统初始化 DML（种子数据）
-- 适用：全新库结构已由 schema.sql 建好后，导入一次系统基线。
-- 包含：内置角色、角色-权限关联、内置证书模板、warm-flow 流程定义、
--       平台级系统账号（admin / keyman1~5 / securityadmin1）。
-- 注意：本文件可重复导入（同名账号/角色幂等由 DROP+INSERT 保证），
--       业务数据请走 baseline-data.sql，不要混到这里。
-- ============================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

-- 清空种子表（保证本脚本可重复执行）
TRUNCATE TABLE `ssl_role_perm`;
TRUNCATE TABLE `ssl_sys_role`;
TRUNCATE TABLE `ssl_cert_template`;
TRUNCATE TABLE `flow_skip`;
TRUNCATE TABLE `flow_node`;
TRUNCATE TABLE `flow_definition`;
-- ssl_sys_user 只清平台级系统账号，业务用户在 baseline 里
DELETE FROM `ssl_sys_user` WHERE id IN (1,2,3,4,5,2117495840921632769,2117500000000000015);

-- ----- ssl_sys_role (11 行) -----

-- ----- ssl_role_perm (160 行) -----

-- ----- ssl_cert_template (3 行) -----

-- ----- flow_definition (4 行) -----

-- ----- flow_node (16 行) -----

-- ----- flow_skip (12 行) -----

-- ----- ssl_sys_user (7 行) -----

SET FOREIGN_KEY_CHECKS=1;
